static void die(int status, int syserr, const char *fmt, ...) /* <=== die */ 
{
	va_list arg_ptr;
	int save = errno;

	fflush(0);
	va_start(arg_ptr, fmt);
	fprintf(stderr, "%s: ", progname);
	vfprintf(stderr, fmt, arg_ptr);
	if (syserr) {
		fprintf(stderr, ": %s", strerror(save));
	}
	fprintf(stderr, "\n");
	va_end(arg_ptr);
	exit(status);
}

static void /* <=== die_if_null */ 
die_if_null(void *t) {
	if (t == NULL)
		die(EX_SYSERR, _("not enough memory"));
}

static void die(const char *msg) /* <=== die */ 
{
	perror(msg);
	exit(1);
}

static int umount_nofollow_support(void) /* <=== umount_nofollow_support */ 
{
	int res = umount2("", UMOUNT_UNUSED);
	if (res != -1 || errno != EINVAL)
		return 0;

	res = umount2("", UMOUNT_NOFOLLOW);
	if (res != -1 || errno != ENOENT)
		return 0;

	return 1;
}

static inline void xstrncpy(char *dest, const char *src, size_t n) /* <=== xstrncpy */ 
{
	strncpy(dest, src, n-1);
	dest[n-1] = 0;
}

